/**
 * 文本步骤功能
 * 支持手动添加纯文本步骤
 * 增强 AI 撰写功能以支持文本和图片混合输入
 */
(function() {
    'use strict';

    var TextStepManager = {
        modal: null,
        textarea: null,
        confirmBtn: null,
        stepsList: null,
        stepCounter: null,

        init: function() {
            this.modal = document.getElementById('textStepModal');
            this.textarea = document.getElementById('textStepContent');
            this.confirmBtn = document.getElementById('confirmTextStep');
            this.stepsList = document.getElementById('stepsList');
            this.stepCounter = null;

            this.bindEvents();
            this.updateStepCounter();
        },

        bindEvents: function() {
            var addBtn = document.getElementById('addTextStepBtn');
            var closeBtn = document.getElementById('closeTextStepModal');
            var cancelBtn = document.getElementById('cancelTextStep');

            if (addBtn) {
                addBtn.addEventListener('click', this.showModal.bind(this));
            }

            if (closeBtn) {
                closeBtn.addEventListener('click', this.hideModal.bind(this));
            }

            if (cancelBtn) {
                cancelBtn.addEventListener('click', this.hideModal.bind(this));
            }

            if (this.modal) {
                this.modal.addEventListener('click', function(e) {
                    if (e.target === this) {
                        this.hideModal();
                    }
                }.bind(this));
            }

            if (this.confirmBtn) {
                this.confirmBtn.addEventListener('click', this.addTextStep.bind(this));
            }

            if (this.textarea) {
                this.textarea.addEventListener('keydown', function(e) {
                    if (e.key === 'Enter' && e.ctrlKey) {
                        this.addTextStep();
                    }
                }.bind(this));
            }

            var clearBtn = document.getElementById('clearBtn');
            if (clearBtn) {
                clearBtn.addEventListener('click', this.updateStepCounter.bind(this));
            }
        },

        showModal: function() {
            if (this.modal) {
                this.modal.classList.add('active');
                if (this.textarea) {
                    this.textarea.value = '';
                    this.textarea.focus();
                }
            }
        },

        hideModal: function() {
            if (this.modal) {
                this.modal.classList.remove('active');
            }
        },

        addTextStep: function() {
            var content = this.textarea.value.trim();

            if (!content) {
                this.showToast('请输入步骤内容');
                return;
            }

            var stepItem = this.createTextStepElement(content);
            this.stepsList.appendChild(stepItem);

            this.saveTextStepsToStorage();
            this.updateStepCounter();
            this.updateExportButton();
            this.hideModal();

            this.showToast('文本步骤已添加');
            this.scrollToBottom();
        },

        createTextStepElement: function(content) {
            var li = document.createElement('li');
            li.className = 'step-text-only';
            li.dataset.type = 'text';
            li.dataset.content = content;
            li.dataset.timestamp = new Date().toISOString();

            li.innerHTML =
                '<div class="text-badge">📝 文本步骤</div>' +
                '<div class="text-content">' + this.escapeHtml(content) + '</div>';

            var deleteBtn = document.createElement('button');
            deleteBtn.className = 'step-delete-btn';
            deleteBtn.innerHTML = '×';
            deleteBtn.title = '删除此步骤';
            deleteBtn.style.cssText = 'position: absolute; top: 8px; right: 8px; background: rgba(0,0,0,0.1); border: none; border-radius: 50%; width: 24px; height: 24px; cursor: pointer; font-size: 14px; color: #666; transition: all 0.2s;';
            deleteBtn.addEventListener('click', function() {
                li.remove();
                this.saveTextStepsToStorage();
                this.updateStepCounter();
                this.updateExportButton();
            }.bind(this));
            li.appendChild(deleteBtn);

            return li;
        },

        escapeHtml: function(text) {
            var div = document.createElement('div');
            div.textContent = text;
            return div.innerHTML;
        },

        saveTextStepsToStorage: function() {
            var textSteps = [];
            var stepElements = this.stepsList.querySelectorAll('li.step-text-only');

            stepElements.forEach(function(step) {
                textSteps.push({
                    content: step.dataset.content,
                    timestamp: step.dataset.timestamp
                });
            });

            chrome.storage.local.set({ textSteps: textSteps });
        },

        updateStepCounter: function() {
            var stepElements = this.stepsList.querySelectorAll('li');
            var textSteps = this.stepsList.querySelectorAll('li.step-text-only');
            var total = stepElements.length;

            var counter = document.querySelector('.step-counter');
            if (!counter) {
                counter = document.createElement('div');
                counter.className = 'step-counter';
                if (this.stepsList.firstChild) {
                    this.stepsList.insertBefore(counter, this.stepsList.firstChild);
                } else {
                    this.stepsList.appendChild(counter);
                }
            }

            if (total === 0) {
                counter.textContent = '暂无步骤';
                counter.classList.remove('warning');
            } else {
                var textCount = textSteps.length;
                if (textCount > 0) {
                    counter.textContent = '共 ' + total + ' 个步骤（含 ' + textCount + ' 个文本步骤）';
                } else {
                    counter.textContent = '共 ' + total + ' 个步骤';
                }
                counter.classList.toggle('warning', total > 20);
            }
        },

        updateExportButton: function() {
            var exportBtn = document.getElementById('exportBtn');
            var clearBtn = document.getElementById('clearBtn');
            var copyBtn = document.getElementById('copyBtn');
            var stepElements = this.stepsList.querySelectorAll('li');

            var hasSteps = stepElements.length > 0;

            if (exportBtn) exportBtn.disabled = !hasSteps;
            if (clearBtn) clearBtn.disabled = !hasSteps;
            if (copyBtn) copyBtn.disabled = !hasSteps;
        },

        scrollToBottom: function() {
            window.scrollTo({ top: document.body.scrollHeight, behavior: 'smooth' });
        },

        showToast: function(message) {
            var toast = document.createElement('div');
            toast.className = 'zhipu-toast';
            toast.textContent = message;
            document.body.appendChild(toast);
            setTimeout(function() {
                toast.remove();
            }, 2000);
        },

        getTextSteps: function() {
            var textSteps = [];
            var stepElements = this.stepsList.querySelectorAll('li.step-text-only');

            stepElements.forEach(function(step, index) {
                textSteps.push({
                    index: index,
                    content: step.dataset.content,
                    element: step
                });
            });

            return textSteps;
        },

        getAllStepsWithContext: function() {
            var steps = [];
            var stepElements = this.stepsList.querySelectorAll('li');

            stepElements.forEach(function(step, index) {
                var isTextOnly = step.classList.contains('step-text-only');
                var img = step.querySelector('img');

                steps.push({
                    index: index,
                    type: isTextOnly ? 'text' : 'image',
                    content: isTextOnly ? step.dataset.content : (img ? img.src : null),
                    element: step
                });
            });

            return steps;
        }
    };

    var AIWriteEnhancer = {
        init: function() {
            this.enhanceAIWrite();
        },

        enhanceAIWrite: function() {
            var zhipuBtn = document.getElementById('zhipuRecognizeBtn');
            if (!zhipuBtn) return;

            var self = this;

            zhipuBtn.addEventListener('click', async function(e) {
                var steps = TextStepManager.getAllStepsWithContext();
                var hasTextSteps = steps.some(function(s) { return s.type === 'text'; });
                var hasImageSteps = steps.some(function(s) { return s.type === 'image'; });

                if (!hasTextSteps && !hasImageSteps) {
                    return;
                }

                e.stopImmediatePropagation();

                if (hasTextSteps && !hasImageSteps) {
                    await self.handleTextOnlySteps(steps);
                } else if (hasImageSteps && !hasTextSteps) {
                    await self.handleImageOnlySteps(steps);
                } else {
                    await self.handleMixedSteps(steps);
                }
            });
        },

        handleImageOnlySteps: async function(steps) {
            var zhipuBtn = document.getElementById('zhipuRecognizeBtn');
            zhipuBtn.disabled = true;
            zhipuBtn.innerText = '稍等';

            var progress = document.getElementById('zhipuProgress');
            var progressBar = document.getElementById('zhipuProgressBar');
            var progressText = document.getElementById('zhipuProgressText');
            var progressTitle = document.getElementById('zhipuProgressTitle');

            progress.style.display = 'block';
            progressTitle.textContent = '智谱识别中...';
            progressBar.style.width = '0%';

            var imageSteps = steps.filter(function(s) { return s.type === 'image'; });

            try {
                await ZhipuVision.loadConfig();
                var config = ZhipuVision.getConfig();

                ZhipuVision.showPromptDialog(config.defaultPrompt, async function(customPrompt) {
                    var successCount = 0;
                    var failCount = 0;
                    var recognitionResults = {};

                    for (var i = 0; i < imageSteps.length; i++) {
                        var percent = Math.round((i / imageSteps.length) * 100);
                        progressBar.style.width = percent + '%';
                        progressText.textContent = '正在识别第 ' + (i + 1) + '/' + imageSteps.length + ' 张图片';

                        try {
                            var result = await ZhipuVision.recognizeImage(imageSteps[i].content, customPrompt);
                            successCount++;
                            var content = result.choices && result.choices[0] && result.choices[0].message ? result.choices[0].message.content : '';

                            if (content) {
                                recognitionResults[imageSteps[i].index] = content;

                                var existingResult = imageSteps[i].element.querySelector('.zhipu-result');
                                if (existingResult) existingResult.remove();

                                var resultDiv = document.createElement('div');
                                resultDiv.className = 'zhipu-result';
                                resultDiv.innerHTML = '<div class="result-title">✨ AI 分析结果</div><div class="result-content">' + content + '</div>';
                                imageSteps[i].element.appendChild(resultDiv);
                            }
                        } catch (error) {
                            failCount++;
                            console.error('图片识别失败:', error);
                        }
                    }

                    progressBar.style.width = '100%';
                    progressTitle.textContent = '识别完成';
                    progressText.textContent = '成功：' + successCount + ' | 失败：' + failCount;

                    if (Object.keys(recognitionResults).length > 0) {
                        chrome.storage.local.set({ zhipuRecognitionResults: recognitionResults });
                    }

                    setTimeout(function() {
                        progress.style.display = 'none';
                        zhipuBtn.disabled = false;
                        zhipuBtn.innerText = 'AI撰写';
                    }, 2000);
                });
            } catch (error) {
                console.error('初始化失败:', error);
                progress.style.display = 'none';
                zhipuBtn.disabled = false;
                zhipuBtn.innerText = 'AI撰写';
            }
        },

        handleTextOnlySteps: async function(steps) {
            var zhipuBtn = document.getElementById('zhipuRecognizeBtn');
            zhipuBtn.disabled = true;
            zhipuBtn.innerText = '稍等';

            var progress = document.getElementById('zhipuProgress');
            var progressBar = document.getElementById('zhipuProgressBar');
            var progressText = document.getElementById('zhipuProgressText');
            var progressTitle = document.getElementById('zhipuProgressTitle');

            progress.style.display = 'block';
            progressTitle.textContent = 'AI 撰写中...';
            progressBar.style.width = '0%';

            var textContents = steps.map(function(s) { return s.content; }).join('\n\n');

            var prompt = this.generateTextOnlyPrompt(textContents);

            try {
                await ZhipuVision.loadConfig();
                var config = ZhipuVision.getConfig();
                var customPrompt = config.defaultPrompt || '请详细描述这张图片的内容';

                ZhipuVision.showPromptDialog(prompt, async function(finalPrompt) {
                    progressText.textContent = '正在生成内容...';

                    try {
                        var result = await ZhipuVision.recognizeText(finalPrompt);

                        if (result && result.choices && result.choices[0] && result.choices[0].message) {
                            var content = result.choices[0].message.content;

                            steps.forEach(function(step) {
                                var existingResult = step.element.querySelector('.zhipu-result');
                                if (existingResult) existingResult.remove();

                                var resultDiv = document.createElement('div');
                                resultDiv.className = 'zhipu-result';
                                resultDiv.innerHTML = '<div class="result-title">✨ AI 撰写结果</div><div class="result-content">' + content + '</div>';
                                step.element.appendChild(resultDiv);
                            });

                            chrome.storage.local.set({
                                zhipuRecognitionResults: { text_only: content }
                            });
                        }

                        progressBar.style.width = '100%';
                        progressTitle.textContent = '撰写完成';
                        progressText.textContent = '已为 ' + steps.length + ' 个文本步骤生成内容';
                    } catch (error) {
                        console.error('AI 撰写失败:', error);
                        progressTitle.textContent = '撰写失败';
                        progressText.textContent = error.message || '请检查网络连接';
                    }

                    setTimeout(function() {
                        progress.style.display = 'none';
                        zhipuBtn.disabled = false;
                        zhipuBtn.innerText = 'AI撰写';
                    }, 2000);
                });
            } catch (error) {
                console.error('初始化失败:', error);
                progress.style.display = 'none';
                zhipuBtn.disabled = false;
                zhipuBtn.innerText = 'AI撰写';
            }
        },

        handleMixedSteps: async function(steps) {
            var zhipuBtn = document.getElementById('zhipuRecognizeBtn');
            zhipuBtn.disabled = true;
            zhipuBtn.innerText = '稍等';

            var progress = document.getElementById('zhipuProgress');
            var progressBar = document.getElementById('zhipuProgressBar');
            var progressText = document.getElementById('zhipuProgressText');
            var progressTitle = document.getElementById('zhipuProgressTitle');

            progress.style.display = 'block';
            progressTitle.textContent = 'AI 智能分析中...';

            var textSteps = steps.filter(function(s) { return s.type === 'text'; });
            var imageSteps = steps.filter(function(s) { return s.type === 'image'; });

            var totalSteps = textSteps.length + imageSteps.length;
            var currentStep = 0;
            var successCount = 0;
            var failCount = 0;
            var recognitionResults = {};

            try {
                await ZhipuVision.loadConfig();

                var textContext = textSteps.map(function(s) { return s.content; }).join('\n\n');

                var imagePrompt = this.generateMixedPrompt(textContext, imageSteps.length);
                var textPrompt = this.generateTextOnlyPrompt(textContext);

                var self = this;

                ZhipuVision.showPromptDialog(imagePrompt, async function(customPrompt) {
                    try {
                        if (textSteps.length > 0) {
                            progressText.textContent = '正在处理 ' + (currentStep + 1) + '/' + totalSteps + '，处理文本步骤...';

                            var fullTextPrompt = textPrompt + '\n\n【参考上下文】\n' + textContext;
                            try {
                                var textResult = await ZhipuVision.recognizeText(fullTextPrompt);
                                if (textResult && textResult.choices && textResult.choices[0] && textResult.choices[0].message) {
                                    var textContent = textResult.choices[0].message.content;
                                    successCount++;

                                    textSteps.forEach(function(step) {
                                        var existingResult = step.element.querySelector('.zhipu-result');
                                        if (existingResult) existingResult.remove();

                                        var resultDiv = document.createElement('div');
                                        resultDiv.className = 'zhipu-result';
                                        resultDiv.innerHTML = '<div class="result-title">✨ AI 扩写结果</div><div class="result-content">' + textContent + '</div>';
                                        step.element.appendChild(resultDiv);
                                    });

                                    recognitionResults['text_expanded'] = textContent;
                                }
                            } catch (err) {
                                failCount++;
                                console.error('文本处理失败:', err);
                            }
                            currentStep++;
                        }

                        for (var i = 0; i < imageSteps.length; i++) {
                            var percent = Math.round((currentStep / totalSteps) * 100);
                            progressBar.style.width = percent + '%';
                            progressText.textContent = '正在处理 ' + (currentStep + 1) + '/' + totalSteps + '，分析图片...';

                            try {
                                var fullPrompt = customPrompt + '\n\n【参考文本上下文】\n' + textContext;
                                var result = await ZhipuVision.recognizeImage(imageSteps[i].content, fullPrompt);

                                successCount++;
                                var content = result.choices && result.choices[0] && result.choices[0].message ? result.choices[0].message.content : '';

                                if (content) {
                                    recognitionResults[imageSteps[i].index] = content;

                                    var existingResult = imageSteps[i].element.querySelector('.zhipu-result');
                                    if (existingResult) existingResult.remove();

                                    var resultDiv = document.createElement('div');
                                    resultDiv.className = 'zhipu-result';
                                    resultDiv.innerHTML = '<div class="result-title">✨ AI 分析结果</div><div class="result-content">' + content + '</div>';
                                    imageSteps[i].element.appendChild(resultDiv);
                                }
                            } catch (error) {
                                failCount++;
                                console.error('图片分析失败:', error);
                            }
                            currentStep++;
                        }

                        progressBar.style.width = '100%';
                        progressTitle.textContent = '分析完成';
                        progressText.textContent = '成功：' + successCount + ' | 失败：' + failCount;

                        if (Object.keys(recognitionResults).length > 0) {
                            chrome.storage.local.set({ zhipuRecognitionResults: recognitionResults });
                        }
                    } catch (error) {
                        console.error('处理失败:', error);
                        progressTitle.textContent = '处理失败';
                        progressText.textContent = error.message || '请检查网络连接';
                    }

                    setTimeout(function() {
                        progress.style.display = 'none';
                        zhipuBtn.disabled = false;
                        zhipuBtn.innerText = 'AI撰写';
                    }, 2000);
                });
            } catch (error) {
                console.error('初始化失败:', error);
                progress.style.display = 'none';
                zhipuBtn.disabled = false;
                zhipuBtn.innerText = 'AI撰写';
            }
        },

        generateTextOnlyPrompt: function(textContent) {
            return '操作步骤扩写\n\n' +
                   '【文本内容】\n' + textContent + '\n\n' +
                   '【要求】\n' +
                   '1. 以提供的文本为主题，围绕它展开详细、专业的描述\n' +
                   '2. 将内容组织成清晰的操作步骤，使用序号标记\n' +
                   '3. 每个步骤描述要具体、完整，便于读者理解\n' +
                   '4. 适当补充必要的细节和注意事项\n' +
                   '5. 输出格式：使用 Markdown 格式，保持段落清晰';
        },

        generateMixedPrompt: function(textContext, imageCount) {
            return '图文综合分析\n\n' +
                   '【参考文本】\n' + textContext + '\n\n' +
                   '【要求】\n' +
                   '1. 优先参考上述文本内容，确保描述与参考信息一致\n' +
                   '2. 结合图片中的实际界面进行描述\n' +
                   '3. 如果图片内容与参考文本相关联，应在描述中体现这种关系\n' +
                   '4. 描述应准确、专业，涵盖关键操作和界面元素\n' +
                   '5. 输出格式：使用 Markdown 格式';
        }
    };

    var CopyEnhancer = {
        init: function() {
            this.enhanceCopy();
        },

        enhanceCopy: function() {
            var copyBtn = document.getElementById('copyBtn');
            if (!copyBtn) return;

            var self = this;

            copyBtn.addEventListener('click', async function(e) {
                var steps = TextStepManager.getAllStepsWithContext();
                var hasTextSteps = steps.some(function(s) { return s.type === 'text'; });

                if (!hasTextSteps) {
                    return true;
                }

                e.stopImmediatePropagation();
                await self.copyWithTextSteps(steps);
            }, true);
        },

        copyWithTextSteps: async function(steps) {
            var recognitionResults = await new Promise(function(resolve) {
                chrome.storage.local.get(['zhipuRecognitionResults'], function(result) {
                    resolve(result.zhipuRecognitionResults || {});
                });
            });

            var markdown = '# 录制步骤\n\n';

            steps.forEach(function(step, index) {
                markdown += '## ' + (step.type === 'text' ? '📝 文本步骤' : '步骤 ' + (index + 1)) + '\n\n';

                if (step.type === 'text') {
                    markdown += step.content + '\n\n';

                    if (recognitionResults && recognitionResults['text_expanded']) {
                        markdown += '### ✨ AI 扩写结果\n\n';
                        markdown += recognitionResults['text_expanded'] + '\n\n';
                    }
                } else {
                    if (step.element) {
                        var titleInput = step.element.querySelector('.step-title-input');
                        if (titleInput && titleInput.value) {
                            markdown += titleInput.value + '\n\n';
                        }
                    }

                    if (step.content) {
                        markdown += '![](' + step.content + ')\n\n';
                    }

                    if (recognitionResults && recognitionResults[step.index] !== undefined) {
                        markdown += '### ✨ AI 分析结果\n\n';
                        markdown += recognitionResults[step.index] + '\n\n';
                    }
                }
            });

            try {
                await navigator.clipboard.writeText(markdown);
                var toast = document.createElement('div');
                toast.className = 'zhipu-toast';
                toast.textContent = 'Markdown 内容已复制到剪贴板！';
                document.body.appendChild(toast);
                setTimeout(function() { toast.remove(); }, 2000);
            } catch (err) {
                var textarea = document.createElement('textarea');
                textarea.value = markdown;
                document.body.appendChild(textarea);
                textarea.select();
                document.execCommand('copy');
                document.body.removeChild(textarea);

                var toast = document.createElement('div');
                toast.className = 'zhipu-toast';
                toast.textContent = 'Markdown 内容已复制到剪贴板！';
                document.body.appendChild(toast);
                setTimeout(function() { toast.remove(); }, 2000);
            }
        }
    };

    document.addEventListener('DOMContentLoaded', function() {
        if (typeof ZhipuVision === 'undefined') {
            console.warn('ZhipuVision 未加载，文本步骤功能将在延迟后初始化');
            setTimeout(function() {
                TextStepManager.init();
                AIWriteEnhancer.init();
                CopyEnhancer.init();
            }, 1000);
        } else {
            TextStepManager.init();
            AIWriteEnhancer.init();
            CopyEnhancer.init();
        }
    });
})();
